  'brand-strategy' => 
  array (
    'slug' => 'brand-strategy',
    'title' => 'Brand Strategy, Positioning & Messaging Framework',
    'short_title' => 'Brand Strategy',
    'parent_slug' => 'branding',
    'parent_name' => 'Branding, Creative & Visual Identity',
    'badge' => 'MARKET MOAT',
    'badge_color' => 'gold',
    'category' => 'creative',
    'category_name' => 'Creative & Identity',
    'icon' => 'fa-solid fa-chess',
    'meta_description' => 'Define your competitive advantage, target buyer personas, value proposition, and brand messaging framework with our brand strategy consulting.',
    'hero_headline' => 'Define Why Customers Should Choose You <span class="gold-gradient-text">Over Every Competitor</span>',
    'hero_lead' => 'Before designing visuals or launching ads, your business needs a clear strategic foundation. We help you articulate your unique value proposition, ideal buyer profiles, and core brand message.',
    'overview' => 'When a company cannot clearly explain what makes it different in 10 seconds, it is forced to compete solely on the lowest price. Our Brand Strategy service helps founders and leadership teams clarify their market positioning. We analyze your competitors, interview stakeholders, define buyer personas, and construct a clear messaging framework that guides all your website copy, sales pitches, and marketing campaigns.',
    'deliverables' => 
    array (
      0 => 
      array (
        'title' => 'Core Brand Architecture & Positioning Framework',
        'desc' => 'Define your vision, mission, purpose, core values, and strategic position relative to market competitors.',
      ),
      1 => 
      array (
        'title' => 'Ideal Customer Profile (ICP) & Persona Archetypes',
        'desc' => 'Detailed profiles of primary decision-makers, their core motivations, emotional triggers, and objections.',
      ),
      2 => 
      array (
        'title' => 'Irresistible Value Proposition & Elevator Pitch',
        'desc' => 'Crisp, compelling articulation of what makes your offering superior, unique, and essential.',
      ),
      3 => 
      array (
        'title' => 'Competitive Moat & White Space Opportunity Mapping',
        'desc' => 'Identify underserved gaps in your competitor landscape where your company can claim undisputed leadership.',
      ),
